contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // Keep domain wide but require _tos non-empty because original function requires it
        vm.assume(_tos.length > 0);
        // As noted, low-level call is made to caddress; a fuzzed address would be EOA (call succeeds and returns true)
