pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from address, caddress (will be a deployed helper), an array of tos, and a value
    function testFuzz_property(address from, uint256 v, address[] memory _tos) public {
        // admissible domain: _tos must be non-empty because contract requires it
        vm.assume(_tos.length > 0);

        // Deploy a benign callee contract that accepts the low-level call.
        // The reference contract's behavior does not depend on callee success, only on the final return value.
        Callee okCallee = new Callee();

        // Call transfer on reference; we observe its return via try/catch and a boolean flag
        bool ok;
        try c.transfer(from, address(okCallee), _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // The general rule: reference returns true for every admissible input (non-empty _tos).
        // Mutant returns false for some inputs; asserting true here will pass on reference and fail on mutant.
        assertTrue(ok);
    }
}

// minimal helper: accepts any call and returns true from fallback (does nothing)
contract Callee {
    fallback() external payable {
        // accept calls; do nothing
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: an address for the from param and a dynamic length for _tos encoded via a seed
    // We pass a helper callee that counts how many times it was invoked.
    function testFuzz_property(address from, uint256 tosLenSeed) public {
        // keep tos length in a reasonable wide bound but >=1 as required by contract
        uint256 len = bound(tosLenSeed, 1, 10);

        // deploy a helper that records number of calls
        CounterCallee helper = new CounterCallee();

        // build an array of distinct addresses to pass as _tos; their values don't matter to C
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            // derive pseudo-random addresses from inputs
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, i, tosLenSeed)))));
        }

        // call transfer on c, routing the caddress argument to our helper
        bool ok;
        try c.transfer(from, address(helper), tos, 42) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call returns (successful or not), the reference implementation guarantees
        // that for any non-empty _tos the contract attempted a call for every element in _tos.
        // Our helper simply increments its counter on each call it receives. We assert that
        // the number of calls the helper observed equals tos.length when the call completed successfully.
        // This property holds for the reference C for all inputs; the mutant that returns early
        // will cause fewer calls to be observed for some inputs and thus fail this assertion there.
        if (ok) {
            // exactly one assertion as required
            assertTrue(helper.callCount() == len);
        } else {
            // If the call reverted, we still must assert something reading c; assert that it reverted is allowed
            // but to keep a single assertion path we assertTrue(false) would fail on reference; instead
            // we assert that callCount is 0 only if the call reverted — reference never reverts for these inputs
            // Since reference doesn't revert, ok should always be true; keep a consistent single assertTrue reading c via helper
            assertTrue(helper.callCount() == 0);
        }
    }
}

// Helper callee that records how many times it was invoked via fallback
contract CounterCallee {
    uint256 public callCount = 0;
    fallback() external payable {
        callCount += 1;
    }
    receive() external payable {
        callCount += 1;
    }
}
